<?php require dirname(__DIR__).'/includes/app.php';$admins=admins();if(!$admins){header('Location:'.site_url('/admin/setup.php'));exit;}if(!is_admin()){header('Location:'.site_url('/admin/login.php'));exit;}$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='add_project'){$list=read_json('projects.json',[]);$name=trim((string)$_POST['name']);$slug=slugify($name);$list[]=['id'=>bin2hex(random_bytes(8)),'slug'=>$slug.'-'.substr(bin2hex(random_bytes(3)),0,6),'name'=>$name,'location'=>trim((string)($_POST['location']??'')),'category'=>trim((string)($_POST['category']??'Framing')),'status'=>trim((string)($_POST['status']??'Completed')),'description'=>trim((string)($_POST['description']??'')),'featured'=>isset($_POST['featured']),'images'=>save_uploaded_images($_FILES['images']??[]),'created_at'=>date(DATE_ATOM)];write_json('projects.json',$list);$notice='Project added.';}if($action==='delete_project'){$id=(string)$_POST['id'];$list=read_json('projects.json',[]);foreach($list as $x)if(($x['id']??'')===$id)foreach($x['images']??[] as $img)delete_project_image($img);$list=array_values(array_filter($list,fn($x)=>($x['id']??'')!==$id));write_json('projects.json',$list);$notice='Project deleted.';}if($action==='add_tab'){$list=read_json('tabs.json',tabs());$label=trim((string)$_POST['label']);$list[]=['id'=>slugify($label).'-'.time(),'label'=>$label,'url'=>trim((string)($_POST['url']??'')),'page_slug'=>(string)($_POST['page_slug']??''),'visible'=>true,'sort'=>(int)($_POST['sort']??50)];write_json('tabs.json',$list);$notice='Navigation tab added.';}if($action==='save_tabs'){$list=read_json('tabs.json',tabs());foreach($list as &$t){$id=$t['id'];$t['label']=trim((string)($_POST['label'][$id]??$t['label']));$t['url']=trim((string)($_POST['url'][$id]??$t['url']??''));$t['page_slug']=(string)($_POST['page_slug'][$id]??'');$t['sort']=(int)($_POST['sort'][$id]??$t['sort']);$t['visible']=isset($_POST['visible'][$id]);}unset($t);write_json('tabs.json',$list);$notice='Navigation updated.';}}$items=projects();$nav=tabs();$pages=custom_pages();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin</title><link rel="stylesheet" href="<?=e(asset_url('/admin/admin.css'))?>"></head><body><aside><div class="admin-logo">GB</div><h2>Galindos Builders</h2><a href="#projects">Projects</a><a href="#new">Add Project</a><a href="#tabs">Navigation Tabs</a><a href="<?=e(site_url('/admin/pages.php'))?>">Custom Pages</a><a href="<?=e(site_url('/admin/content.php'))?>">Homepage / Services / SEO / Quotes</a><a href="<?=e(site_url('/'))?>" target="_blank">View Website ↗</a><a href="<?=e(site_url('/admin/logout.php'))?>">Sign Out</a></aside><main class="admin-main"><header><div><small>WEBSITE ADMIN</small><h1>Content Dashboard</h1></div></header><?php if($notice):?><div class="success"><?=e($notice)?></div><?php endif;?><section class="stats"><article><strong><?=count($items)?></strong><span>Projects</span></article><article><strong><?=count($nav)?></strong><span>Navigation Tabs</span></article><article><strong><?=count($pages)?></strong><span>Custom Pages</span></article></section><section class="panel" id="new"><h2>Add Project / Job</h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_project"><label>Custom Job Name<input name="name" required></label><label>Location<input name="location"></label><label>Category<input name="category" placeholder="Wood Framing"></label><label>Status<input name="status" value="Completed"></label><label class="full">Description<textarea name="description" rows="5"></textarea></label><label class="full">Photos<input type="file" name="images[]" accept="image/*" multiple></label><label class="check full"><input type="checkbox" name="featured" checked> Featured</label><button>Add Project</button></form></section><section class="panel" id="projects"><h2>Projects</h2><div class="table-wrap"><table><thead><tr><th>Job</th><th>Category</th><th>Photos</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><b><?=e($p['name'])?></b><br><?=e($p['location'])?></td><td><?=e($p['category'])?></td><td><?=count($p['images']??[])?></td><td><a href="<?=e(site_url('/admin/edit-project.php?id='.urlencode($p['id'])))?>">Edit / Gallery</a><form method="post" style="display:inline" onsubmit="return confirm('Delete this project?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_project"><input type="hidden" name="id" value="<?=e($p['id'])?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel" id="tabs"><h2>Custom Navigation Tabs</h2><p>Each tab can point to a custom CMS page or a manual URL. Create pages under <a href="<?=e(site_url('/admin/pages.php'))?>">Custom Pages</a>.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_tabs"><div class="table-wrap"><table><thead><tr><th>Show</th><th>Label</th><th>Custom Page</th><th>Manual URL</th><th>Order</th></tr></thead><tbody><?php foreach($nav as $t):$id=$t['id'];?><tr><td><input type="checkbox" name="visible[<?=e($id)?>]" <?=!empty($t['visible'])?'checked':''?>></td><td><input name="label[<?=e($id)?>]" value="<?=e($t['label'])?>"></td><td><select name="page_slug[<?=e($id)?>]"><option value="">Use manual URL</option><?php foreach($pages as $pg):?><option value="<?=e($pg['slug'])?>" <?=($t['page_slug']??'')===$pg['slug']?'selected':''?>><?=e($pg['title'])?></option><?php endforeach;?></select></td><td><input name="url[<?=e($id)?>]" value="<?=e($t['url']??'')?>"></td><td><input type="number" name="sort[<?=e($id)?>]" value="<?=e((string)$t['sort'])?>"></td></tr><?php endforeach;?></tbody></table></div><button>Save Navigation</button></form><hr><h3>Add Navigation Tab</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_tab"><label>Tab Label<input name="label" required placeholder="Our Company"></label><label>Custom Page<select name="page_slug"><option value="">Use manual URL</option><?php foreach($pages as $pg):?><option value="<?=e($pg['slug'])?>"><?=e($pg['title'])?></option><?php endforeach;?></select></label><label>Manual URL<input name="url" placeholder="/#contact or https://..."></label><label>Order<input type="number" name="sort" value="50"></label><button>Add Tab</button></form></section></main></body></html>